-- State transitions declared for StoredFile (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION bucket.stored_files_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'deleted'), ('deleted', 'active'), ('deleted', 'purged'), ('processing', 'active'), ('processing', 'quarantined'), ('quarantined', 'active'), ('quarantined', 'deleted'), ('uploading', 'processing'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: stored_files.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS stored_files_status_transition_check ON bucket.stored_files;
CREATE TRIGGER stored_files_status_transition_check
    BEFORE UPDATE OF "status" ON bucket.stored_files
    FOR EACH ROW EXECUTE FUNCTION bucket.stored_files_status_transition_check();
